CREATE TYPE "IncidentLifecycleStatus" AS ENUM ('OPEN','ACKNOWLEDGED','ASSIGNED','IN_PROGRESS','RESOLVED','CLOSED');
CREATE TYPE "IncidentSeverityLevel" AS ENUM ('LOW','MEDIUM','HIGH','CRITICAL');
ALTER TABLE "OperationalIncident" ADD COLUMN "lifecycleStatus" "IncidentLifecycleStatus" NOT NULL DEFAULT 'OPEN', ADD COLUMN "severityLevel" "IncidentSeverityLevel" NOT NULL DEFAULT 'MEDIUM', ADD COLUMN "kind" TEXT NOT NULL DEFAULT 'ALERT', ADD COLUMN "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, ADD COLUMN "resolvedAt" TIMESTAMP(3), ADD COLUMN "closedAt" TIMESTAMP(3), ADD COLUMN "version" INTEGER NOT NULL DEFAULT 0;
UPDATE "OperationalIncident" SET "lifecycleStatus"=(CASE WHEN lower("status")='closed' THEN 'CLOSED' WHEN lower("status")='resolved' THEN 'RESOLVED' WHEN lower("status")='in_progress' THEN 'IN_PROGRESS' WHEN "ownerId" IS NOT NULL THEN 'ASSIGNED' WHEN lower("status")='acknowledged' OR (lower("status")='escalated' AND EXISTS (SELECT 1 FROM "OperationalIncidentEvent" e WHERE e."incidentId"="OperationalIncident"."id" AND e."action"='acknowledge')) THEN 'ACKNOWLEDGED' ELSE 'OPEN' END)::"IncidentLifecycleStatus", "severityLevel"=(CASE WHEN lower("severity")='critical' THEN 'CRITICAL' WHEN lower("severity")='high' THEN 'HIGH' WHEN lower("severity")='low' THEN 'LOW' ELSE 'MEDIUM' END)::"IncidentSeverityLevel", "kind"=CASE WHEN "id" IN (SELECT "id" FROM "IncidentEvent" WHERE "simulation"=true) THEN 'SIMULATED_SOS' WHEN "ruleId" IS NOT NULL THEN 'HARDWARE_RULE' ELSE 'ALERT' END, "updatedAt"=COALESCE((SELECT MAX(e."createdAt") FROM "OperationalIncidentEvent" e WHERE e."incidentId"="OperationalIncident"."id"),"createdAt");
UPDATE "OperationalIncident" SET "resolvedAt"=(SELECT MAX(e."createdAt") FROM "OperationalIncidentEvent" e WHERE e."incidentId"="OperationalIncident"."id" AND e."action"='resolve') WHERE "lifecycleStatus"='RESOLVED';
ALTER TABLE "OperationalIncidentEvent" ADD COLUMN "fromStatus" "IncidentLifecycleStatus", ADD COLUMN "toStatus" "IncidentLifecycleStatus", ADD COLUMN "ownerId" TEXT, ADD COLUMN "escalationRuleId" TEXT;
CREATE TABLE "IncidentEscalationRule" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"afterMinutes" INTEGER NOT NULL,"targetSeverity" "IncidentSeverityLevel" NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT false,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "OperationalIncident_lifecycle_created_id" ON "OperationalIncident"("lifecycleStatus","createdAt","id");

ALTER TABLE "OperationalIncident" ADD COLUMN "sosEventId" TEXT, ADD COLUMN "dedupKey" TEXT;
-- Import unmatched historical SOS records without changing or deleting their original history.
INSERT INTO "OperationalIncident" ("id","deviceId","workerId","severity","severityLevel","kind","message","simulation","status","lifecycleStatus","createdAt","updatedAt") SELECT e."id",e."deviceId",e."workerId",'critical','CRITICAL','SIMULATED_SOS',e."message",true,'open','OPEN',e."receivedAt",e."receivedAt" FROM "IncidentEvent" e WHERE e."simulation"=true AND NOT EXISTS (SELECT 1 FROM "OperationalIncident" i WHERE i."id"=e."id");
INSERT INTO "OperationalIncidentEvent" ("id","incidentId","actorId","action","note","createdAt","toStatus") SELECT 'import-sos:' || e."id",e."id",'migration','imported','Historical simulated SOS imported; prior lifecycle was not tracked.',e."receivedAt",'OPEN' FROM "IncidentEvent" e WHERE e."simulation"=true AND NOT EXISTS (SELECT 1 FROM "OperationalIncidentEvent" a WHERE a."incidentId"=e."id");
CREATE UNIQUE INDEX "OperationalIncident_sosEventId_key" ON "OperationalIncident"("sosEventId");
CREATE UNIQUE INDEX "OperationalIncident_dedupKey_key" ON "OperationalIncident"("dedupKey");
WITH candidates AS (SELECT "id",'sos:' || "deviceId" AS key,row_number() OVER (PARTITION BY "deviceId" ORDER BY "createdAt" DESC,"id" DESC) AS n FROM "OperationalIncident" WHERE "kind"='SIMULATED_SOS' AND "deviceId" IS NOT NULL AND "lifecycleStatus" NOT IN ('RESOLVED','CLOSED')) UPDATE "OperationalIncident" i SET "dedupKey"=c.key FROM candidates c WHERE i."id"=c."id" AND c.n=1;
DROP INDEX IF EXISTS "OperationalIncident_open_rule_device";
CREATE UNIQUE INDEX "OperationalIncident_open_rule_device" ON "OperationalIncident"("ruleId","deviceId") WHERE "ruleId" IS NOT NULL AND "lifecycleStatus" NOT IN ('RESOLVED','CLOSED');
